/* prog43_catalan.c
 * Reimplementation of the original obfuscated binary.
 * Behaviour:
 *   - No argument      → prints "NO_INPUT"
 *   - Invalid integer → prints "BAD_INPUT"
 *   - n <= 0          → prints "BAD_INPUT"
 *   - n > 30          → prints "OUT_OF_RANGE"
 *   - otherwise       → prints the n‑th Catalan number (1‑based)
 *
 * The program uses only standard C library functions.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_N 30

/* Compute Catalan numbers C0..C_MAX_N using 64‑bit signed arithmetic.
 * The result array is indexed by the standard Catalan index: cat[0] = C0 = 1,
 * cat[1] = C1 = 1, cat[2] = C2 = 2, ... */
static void compute_catalan(long long cat[MAX_N + 1])
{
    cat[0] = 1;                     /* C0 */
    for (int k = 1; k <= MAX_N; ++k) {
        long long sum = 0;
        for (int i = 0; i < k; ++i) {
            sum += cat[i] * cat[k - 1 - i];
        }
        cat[k] = sum;               /* Ck */
    }
}

/* Return 1 if the whole string `s` is a valid decimal integer and store it in *out.
 * The function rejects empty strings, leading/trailing spaces and any non‑digit
 * characters.  It also checks for overflow/underflow. */
static int parse_long(const char *s, long *out)
{
    if (s == NULL || *s == '\0')
        return 0;

    char *endptr;
    errno = 0;
    long val = strtol(s, &endptr, 10);

    /* strtol must have consumed the whole string and not set errno */
    if (errno != 0 || *endptr != '\0')
        return 0;

    *out = val;
    return 1;
}

int main(int argc, char *argv[])
{
    /* ----- NO INPUT --------------------------------------------------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* ----- PARSE INPUT ------------------------------------------------ */
    long n;
    if (!parse_long(argv[1], &n) || n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* ----- RANGE CHECK ------------------------------------------------ */
    if (n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- CATALAN CALCULATION ---------------------------------------- */
    long long cat[MAX_N + 1];
    compute_catalan(cat);

    /* The original program prints the n‑th Catalan number where the
     * sequence is 1‑based (C1 = 1, C2 = 2, …).  Our table stores C0 at index 0,
     * so the desired value is cat[n]. */
    printf("%lld\n", cat[n]);

    return 0;
}
